## solutions

#### brute force (timeout)

```cpp
#include <vector>
#include <algorithm>

std::vector<int> intersection(std::vector<int> a, std::vector<int> b) {
  std::vector<int> result;

  for (int el : a) {
    if (std::find(b.begin(), b.end(), el) != b.end()) {
      result.push_back(el);
    }
  }

  return result;
}
```

+ n = length of array a, m = length of array b
+ Time: O(n*m)
+ Space: O(min(n,m))



#### using set (pass)

```cpp
#include <vector>
#include <unordered_set>

std::vector<int> intersection(std::vector<int> a, std::vector<int> b) {
  std::unordered_set<int> setA;

  for (int el : a) {
    setA.insert(el);
  }

  std::vector<int> result;
  for (int el : b) {
    if (setA.count(el) > 0) {
      result.push_back(el);
    }
  }

  return result;
}
```

+ n = length of array a, m = length of array b
+ Time: O(n+m)
+ Space: O(n)
